INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('robić', 'to do/make (impf)', 'делать (несов.)', 'verb', NULL, 'B1', 426, 'rɔbit͡ɕ', 'Co robisz wieczorem?', 'What do you do in the evening?', 'Что ты делаешь вечером?'),
('zrobić', 'to do/make (pf)', 'сделать (сов.)', 'verb', NULL, 'B1', 427, 'zrɔbit͡ɕ', 'Muszę to zrobić dziś.', 'I must do this today.', 'Я должен это сделать сегодня.'),
('pisać', 'to write (impf)', 'писать (несов.)', 'verb', NULL, 'B1', 428, 'pisat͡ɕ', 'Piszę list do przyjaciela.', 'I am writing a letter to a friend.', 'Я пишу письмо другу.'),
('napisać', 'to write (pf)', 'написать (сов.)', 'verb', NULL, 'B1', 429, 'napisat͡ɕ', 'Napisałem dwa listy.', 'I wrote two letters.', 'Я написал два письма.'),
('czytać', 'to read (impf)', 'читать (несов.)', 'verb', NULL, 'B1', 430, 't͡ʂɨtat͡ɕ', 'Czytam książkę.', 'I am reading a book.', 'Я читаю книгу.'),
('przeczytać', 'to read (pf)', 'прочитать (сов.)', 'verb', NULL, 'B1', 431, 'pʂɛt͡ʂɨtat͡ɕ', 'Przeczytałem całą książkę.', 'I read the whole book.', 'Я прочитал всю книгу.'),
('uczyć się', 'to study/learn (impf)', 'учиться (несов.)', 'verb', NULL, 'B1', 432, 'ut͡ʂɨt͡ɕ ɕɛ', 'Uczę się polskiego.', 'I am learning Polish.', 'Я изучаю польский.'),
('nauczyć się', 'to learn (pf)', 'выучить (сов.)', 'verb', NULL, 'B1', 433, 'naut͡ʂɨt͡ɕ ɕɛ', 'Nauczyłem się nowych słów.', 'I learned new words.', 'Я выучил новые слова.'),
('kupować', 'to buy (impf)', 'покупать (несов.)', 'verb', NULL, 'B1', 434, 'kupɔvat͡ɕ', 'Kupuję chleb codziennie.', 'I buy bread every day.', 'Я покупаю хлеб каждый день.'),
('kupić', 'to buy (pf)', 'купить (сов.)', 'verb', NULL, 'B1', 435, 'kupit͡ɕ', 'Kupiłem nowy samochód.', 'I bought a new car.', 'Я купил новую машину.'),
('dawać', 'to give (impf)', 'давать (несов.)', 'verb', NULL, 'B1', 436, 'davat͡ɕ', 'Daję mu pieniądze co miesiąc.', 'I give him money every month.', 'Я даю ему деньги каждый месяц.'),
('dać', 'to give (pf)', 'дать (сов.)', 'verb', NULL, 'B1', 437, 'dat͡ɕ', 'Dałem mu prezent.', 'I gave him a gift.', 'Я дал ему подарок.'),
('brać', 'to take (impf)', 'брать (несов.)', 'verb', NULL, 'B1', 438, 'brat͡ɕ', 'Biorę parasol.', 'I am taking an umbrella.', 'Я беру зонт.'),
('wziąć', 'to take (pf)', 'взять (сов.)', 'verb', NULL, 'B1', 439, 'vʑɔ̃t͡ɕ', 'Wziąłem klucze.', 'I took the keys.', 'Я взял ключи.'),
('otwierać', 'to open (impf)', 'открывать (несов.)', 'verb', NULL, 'B1', 440, 'ɔtfjɛrat͡ɕ', 'Otwier am okno co rano.', 'I open the window every morning.', 'Я открываю окно каждое утро.'),
('otworzyć', 'to open (pf)', 'открыть (сов.)', 'verb', NULL, 'B1', 441, 'ɔtfɔʐɨt͡ɕ', 'Otworzyłem drzwi.', 'I opened the door.', 'Я открыл дверь.'),
('zamykać', 'to close (impf)', 'закрывать (несов.)', 'verb', NULL, 'B1', 442, 'zamɨkat͡ɕ', 'Zamykam sklep o 18:00.', 'I close the shop at 6 PM.', 'Я закрываю магазин в 18:00.'),
('zamknąć', 'to close (pf)', 'закрыть (сов.)', 'verb', NULL, 'B1', 443, 'zamknɔ̃t͡ɕ', 'Zamknąłem okno.', 'I closed the window.', 'Я закрыл окно.'),
('rozumieć', 'to understand (impf)', 'понимать (несов.)', 'verb', NULL, 'B1', 444, 'rɔzumjɛt͡ɕ', 'Rozumiem po polsku.', 'I understand Polish.', 'Я понимаю по-польски.'),
('zrozumieć', 'to understand (pf)', 'понять (сов.)', 'verb', NULL, 'B1', 445, 'zrɔzumjɛt͡ɕ', 'Zrozumiałem tę lekcję.', 'I understood this lesson.', 'Я понял этот урок.'),
('kończyć', 'to finish (impf)', 'заканчивать (несов.)', 'verb', NULL, 'B1', 446, 'kɔɲt͡ʂɨt͡ɕ', 'Kończę pracę o 17:00.', 'I finish work at 5 PM.', 'Я заканчиваю работу в 17:00.'),
('skończyć', 'to finish (pf)', 'закончить (сов.)', 'verb', NULL, 'B1', 447, 'skɔɲt͡ʂɨt͡ɕ', 'Skończyłem uniwersytet.', 'I finished university.', 'Я закончил университет.'),
('zaczynać', 'to begin (impf)', 'начинать (несов.)', 'verb', NULL, 'B1', 448, 'zat͡ʂɨnat͡ɕ', 'Zaczynam pracę o 9:00.', 'I start work at 9 AM.', 'Я начинаю работу в 9:00.'),
('zacząć', 'to begin (pf)', 'начать (сов.)', 'verb', NULL, 'B1', 449, 'zat͡ʂɔ̃t͡ɕ', 'Zacząłem naukę polskiego.', 'I started learning Polish.', 'Я начал учить польский.'),
('znajdować', 'to find (impf)', 'находить (несов.)', 'verb', NULL, 'B1', 450, 'znajdɔvat͡ɕ', 'Znajduję klucze w szufladzie.', 'I find keys in the drawer.', 'Я нахожу ключи в ящике.'),
('znaleźć', 'to find (pf)', 'найти (сов.)', 'verb', NULL, 'B1', 451, 'znalɛʑt͡ɕ', 'Znalazłem portfel.', 'I found my wallet.', 'Я нашёл кошелёк.'),
('tracić', 'to lose (impf)', 'терять (несов.)', 'verb', NULL, 'B1', 452, 'trat͡ɕit͡ɕ', 'Tracę czas.', 'I am wasting time.', 'Я теряю время.'),
('stracić', 'to lose (pf)', 'потерять (сов.)', 'verb', NULL, 'B1', 453, 'strat͡ɕit͡ɕ', 'Straciłem klucze.', 'I lost my keys.', 'Я потерял ключи.'),
('wracać', 'to return (impf)', 'возвращаться (несов.)', 'verb', NULL, 'B1', 454, 'vrat͡sat͡ɕ', 'Wracam do domu o 18:00.', 'I return home at 6 PM.', 'Я возвращаюсь домой в 18:00.'),
('wrócić', 'to return (pf)', 'вернуться (сов.)', 'verb', NULL, 'B1', 455, 'vrut͡ɕit͡ɕ', 'Wróciłem z wakacji.', 'I returned from vacation.', 'Я вернулся из отпуска.'),
('wyjeżdżać', 'to leave/depart (impf)', 'уезжать (несов.)', 'verb', NULL, 'B1', 456, 'vɨjɛʐd͡ʐat͡ɕ', 'Wyjeżdżam za granicę co roku.', 'I travel abroad every year.', 'Я уезжаю за границу каждый год.'),
('wyjechać', 'to leave/depart (pf)', 'уехать (сов.)', 'verb', NULL, 'B1', 457, 'vɨjɛxat͡ɕ', 'Wyjechałem do Polski.', 'I left for Poland.', 'Я уехал в Польшу.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('nauczyciel', 'teacher (m)', 'учитель', 'noun', 'masculine', 'B1', 458, 'naut͡ʂɨt͡ɕɛl', 'Jestem nauczycielem.', 'I am a teacher.', 'Я учитель.'),
('nauczycielka', 'teacher (f)', 'учительница', 'noun', 'feminine', 'B1', 459, 'naut͡ʂɨt͡ɕɛlka', 'Ona jest nauczycielką.', 'She is a teacher.', 'Она учительница.'),
('lekarz', 'doctor (m)', 'врач', 'noun', 'masculine', 'B1', 460, 'lɛkaʂ', 'Mój brat jest lekarzem.', 'My brother is a doctor.', 'Мой брат врач.'),
('lekarka', 'doctor (f)', 'врач (ж)', 'noun', 'feminine', 'B1', 461, 'lɛkarka', 'Ona pracuje lekarką.', 'She works as a doctor.', 'Она работает врачом.'),
('inżynier', 'engineer', 'инженер', 'noun', 'masculine', 'B1', 462, 'inʐɨɲɛr', 'Pracuję inżynierem.', 'I work as an engineer.', 'Я работаю инженером.'),
('programista', 'programmer', 'программист', 'noun', 'masculine', 'B1', 463, 'prɔgramista', 'Jest programistą.', 'He is a programmer.', 'Он программист.'),
('kierowca', 'driver', 'водитель', 'noun', 'masculine', 'B1', 464, 'kʲɛrɔft͡sa', 'Pracuję kierowcą.', 'I work as a driver.', 'Я работаю водителем.'),
('pielęgniarka', 'nurse', 'медсестра', 'noun', 'feminine', 'B1', 465, 'pʲɛlɛŋɲarka', 'Ona jest pielęgniarką.', 'She is a nurse.', 'Она медсестра.'),
('prawnik', 'lawyer', 'юрист', 'noun', 'masculine', 'B1', 466, 'pravɲik', 'Mój ojciec jest prawnikiem.', 'My father is a lawyer.', 'Мой отец юрист.'),
('księgowy', 'accountant', 'бухгалтер', 'noun', 'masculine', 'B1', 467, 'kɕɛŋgɔvɨ', 'Pracuje księgowym.', 'He works as an accountant.', 'Он работает бухгалтером.'),
('sprzedawca', 'salesperson (m)', 'продавец', 'noun', 'masculine', 'B1', 468, 'spʂɛdaft͡sa', 'Jest sprzedawcą w sklepie.', 'He is a salesperson in a shop.', 'Он продавец в магазине.'),
('kucharz', 'cook/chef', 'повар', 'noun', 'masculine', 'B1', 469, 'kuxaʂ', 'Pracuję kucharzem.', 'I work as a cook.', 'Я работаю поваром.'),
('tłumacz', 'translator', 'переводчик', 'noun', 'masculine', 'B1', 470, 'twumat͡ʂ', 'Ona jest tłumaczem.', 'She is a translator.', 'Она переводчик.'),
('dziennikarz', 'journalist', 'журналист', 'noun', 'masculine', 'B1', 471, 'd͡ʑɛɲɲikaʂ', 'Pracuje dziennikarzem.', 'He works as a journalist.', 'Он работает журналистом.'),
('artysta', 'artist', 'художник', 'noun', 'masculine', 'B1', 472, 'artɨsta', 'Jest artystą.', 'He is an artist.', 'Он художник.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('ołówek', 'pencil', 'карандаш', 'noun', 'masculine', 'B1', 473, 'ɔwuvɛk', 'Piszę ołówkiem.', 'I write with a pencil.', 'Я пишу карандашом.'),
('długopis', 'pen', 'ручка', 'noun', 'masculine', 'B1', 474, 'dwugɔpis', 'Podpisuję długopisem.', 'I sign with a pen.', 'Я подписываю ручкой.'),
('nóż', 'knife', 'нож', 'noun', 'masculine', 'B1', 475, 'nuʃ', 'Kroję nożem.', 'I cut with a knife.', 'Я режу ножом.'),
('widelec', 'fork', 'вилка', 'noun', 'masculine', 'B1', 476, 'vid ɛlɛt͡s', 'Jem widelcem.', 'I eat with a fork.', 'Я ем вилкой.'),
('łyżka', 'spoon', 'ложка', 'noun', 'feminine', 'B1', 477, 'wɨʃka', 'Mieszam łyżką.', 'I stir with a spoon.', 'Я мешаю ложкой.'),
('młotek', 'hammer', 'молоток', 'noun', 'masculine', 'B1', 478, 'mwɔtɛk', 'Biję młotkiem.', 'I hit with a hammer.', 'Я бью молотком.'),
('piła', 'saw', 'пила', 'noun', 'feminine', 'B1', 479, 'piwa', 'Ciął piłą.', 'He cut with a saw.', 'Он пилил пилой.'),
('klucz', 'key', 'ключ', 'noun', 'masculine', 'B1', 480, 'klut͡ʂ', 'Otwieram kluczem.', 'I open with a key.', 'Я открываю ключом.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('większy', 'bigger', 'больше', 'adjective', 'masculine', 'B1', 481, 'vjɛŋkʂɨ', 'Ten dom jest większy.', 'This house is bigger.', 'Этот дом больше.'),
('największy', 'biggest', 'самый большой', 'adjective', 'masculine', 'B1', 482, 'najvjɛŋkʂɨ', 'To największy dom.', 'This is the biggest house.', 'Это самый большой дом.'),
('mniejszy', 'smaller', 'меньше', 'adjective', 'masculine', 'B1', 483, 'mɲɛjʃɨ', 'Mieszkanie jest mniejsze.', 'The apartment is smaller.', 'Квартира меньше.'),
('najmniejszy', 'smallest', 'самый маленький', 'adjective', 'masculine', 'B1', 484, 'najmɲɛjʃɨ', 'To najmniejszy pokój.', 'This is the smallest room.', 'Это самая маленькая комната.'),
('lepszy', 'better', 'лучше', 'adjective', 'masculine', 'B1', 485, 'lɛpʂɨ', 'To jest lepszy pomysł.', 'This is a better idea.', 'Это лучшая идея.'),
('najlepszy', 'best', 'самый лучший', 'adjective', 'masculine', 'B1', 486, 'najlɛpʂɨ', 'On jest najlepszy.', 'He is the best.', 'Он самый лучший.'),
('gorszy', 'worse', 'хуже', 'adjective', 'masculine', 'B1', 487, 'gɔrʂɨ', 'To jest gorsze.', 'This is worse.', 'Это хуже.'),
('najgorszy', 'worst', 'самый худший', 'adjective', 'masculine', 'B1', 488, 'najgɔrʂɨ', 'To najgorszy dzień.', 'This is the worst day.', 'Это самый плохой день.'),
('ładniejszy', 'prettier', 'красивее', 'adjective', 'masculine', 'B1', 489, 'wadɲɛjʃɨ', 'Ta sukienka jest ładniejsza.', 'This dress is prettier.', 'Это платье красивее.'),
('najładniejszy', 'prettiest', 'самый красивый', 'adjective', 'masculine', 'B1', 490, 'najwadɲɛjʃɨ', 'To najładniejszy obraz.', 'This is the prettiest painting.', 'Это самая красивая картина.'),
('starszy', 'older', 'старше', 'adjective', 'masculine', 'B1', 491, 'starʃɨ', 'Mój brat jest starszy.', 'My brother is older.', 'Мой брат старше.'),
('młodszy', 'younger', 'младше', 'adjective', 'masculine', 'B1', 492, 'mwɔt͡ʂɨ', 'Siostra jest młodsza.', 'Sister is younger.', 'Сестра младше.'),
('tańszy', 'cheaper', 'дешевле', 'adjective', 'masculine', 'B1', 493, 'taɲʃɨ', 'Ten samochód jest tańszy.', 'This car is cheaper.', 'Эта машина дешевле.'),
('droższy', 'more expensive', 'дороже', 'adjective', 'masculine', 'B1', 494, 'drɔʐʂɨ', 'Dom jest droższy.', 'The house is more expensive.', 'Дом дороже.'),
('łatwiejszy', 'easier', 'легче', 'adjective', 'masculine', 'B1', 495, 'watvʲɛjʃɨ', 'To zadanie jest łatwiejsze.', 'This task is easier.', 'Это задание легче.'),
('trudniejszy', 'more difficult', 'труднее', 'adjective', 'masculine', 'B1', 496, 'trudɲɛjʃɨ', 'Egzamin jest trudniejszy.', 'The exam is more difficult.', 'Экзамен труднее.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('musieć', 'must, have to', 'должен', 'verb', NULL, 'B1', 497, 'muɕɛt͡ɕ', 'Muszę iść do pracy.', 'I must go to work.', 'Я должен идти на работу.'),
('muszę', 'I must', 'я должен', 'verb', NULL, 'B1', 498, 'muʃɛ', 'Muszę się uczyć.', 'I must study.', 'Я должен учиться.'),
('musisz', 'you must', 'ты должен', 'verb', NULL, 'B1', 499, 'muɕiʃ', 'Musisz to zrobić.', 'You must do this.', 'Ты должен это сделать.'),
('powinien', 'should (m)', 'должен бы', 'modal', 'masculine', 'B1', 500, 'pɔviɲɛn', 'Powinienem więcej się uczyć.', 'I should study more.', 'Я должен бы больше учиться.'),
('powinna', 'should (f)', 'должна бы', 'modal', 'feminine', 'B1', 501, 'pɔviɲɲa', 'Powinna odpocząć.', 'She should rest.', 'Она должна бы отдохнуть.'),
('powinno', 'should (n)', 'должно бы', 'modal', 'neuter', 'B1', 502, 'pɔviɲɲɔ', 'To powinno działać.', 'This should work.', 'Это должно работать.'),
('wolno', 'allowed, may', 'можно', 'adverb', NULL, 'B1', 503, 'vɔlnɔ', 'Czy wolno palić?', 'Is smoking allowed?', 'Можно курить?'),
('można', 'one can/may', 'можно', 'adverb', NULL, 'B1', 504, 'mɔʐna', 'Można tu fotografować?', 'Can one take photos here?', 'Здесь можно фотографировать?'),
('trzeba', 'one must, it''s necessary', 'нужно', 'adverb', NULL, 'B1', 505, 'tʂɛba', 'Trzeba się uczyć.', 'One must study.', 'Нужно учиться.'),
('nie wolno', 'not allowed, forbidden', 'нельзя', 'adverb', NULL, 'B1', 506, 'ɲɛ vɔlnɔ', 'Nie wolno palić.', 'Smoking is forbidden.', 'Курить нельзя.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('ponieważ', 'because (formal)', 'потому что', 'conjunction', NULL, 'B1', 507, 'pɔɲɛvaʃ', 'Nie poszedłem, ponieważ byłem chory.', 'I didn''t go because I was sick.', 'Я не пошёл, потому что был болен.'),
('bo', 'because (informal)', 'потому что', 'conjunction', NULL, 'B1', 508, 'bɔ', 'Zostałem w domu, bo padało.', 'I stayed home because it was raining.', 'Я остался дома, потому что шёл дождь.'),
('chociaż', 'although', 'хотя', 'conjunction', NULL, 'B1', 509, 'xɔt͡ɕaʃ', 'Poszedłem, chociaż było zimno.', 'I went although it was cold.', 'Я пошёл, хотя было холодно.'),
('mimo że', 'despite that, although', 'несмотря на то что', 'conjunction', NULL, 'B1', 510, 'mimɔ ʐɛ', 'Mimo że padało, poszliśmy.', 'Despite it raining, we went.', 'Несмотря на дождь, мы пошли.'),
('kiedy', 'when', 'когда', 'conjunction', NULL, 'B1', 511, 'kʲɛdɨ', 'Kiedy wrócę, zadzwonię.', 'When I return, I''ll call.', 'Когда вернусь, позвоню.'),
('gdy', 'when', 'когда', 'conjunction', NULL, 'B1', 512, 'gdɨ', 'Gdy byłem dzieckiem...', 'When I was a child...', 'Когда я был ребёнком...'),
('żeby', 'in order to, so that', 'чтобы', 'conjunction', NULL, 'B1', 513, 'ʐɛbɨ', 'Uczę się, żeby zdać egzamin.', 'I study in order to pass the exam.', 'Я учусь, чтобы сдать экзамен.'),
('jeśli', 'if', 'если', 'conjunction', NULL, 'B1', 514, 'jɛɕli', 'Jeśli będzie padać, zostanę.', 'If it rains, I''ll stay.', 'Если будет дождь, я останусь.'),
('jeżeli', 'if', 'если', 'conjunction', NULL, 'B1', 515, 'jɛʐɛli', 'Jeżeli przyjdziesz, będę szczęśliwy.', 'If you come, I''ll be happy.', 'Если ты придёшь, я буду счастлив.'),
('więc', 'so, therefore', 'так что', 'conjunction', NULL, 'B1', 516, 'vjɛnt͡s', 'Jestem zmęczony, więc idę spać.', 'I''m tired, so I''m going to sleep.', 'Я устал, так что иду спать.'),
('dlatego', 'therefore, that''s why', 'поэтому', 'conjunction', NULL, 'B1', 517, 'dlatɛgɔ', 'Pada deszcz, dlatego zostanę.', 'It''s raining, that''s why I''ll stay.', 'Идёт дождь, поэтому я останусь.'),
('jednak', 'however', 'однако', 'conjunction', NULL, 'B1', 518, 'jɛdnak', 'Chciałem przyjść, jednak nie mogłem.', 'I wanted to come, however I couldn''t.', 'Я хотел прийти, однако не смог.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('ból', 'pain', 'боль', 'noun', 'masculine', 'B1', 519, 'bul', 'Mam ból głowy.', 'I have a headache.', 'У меня болит голова.'),
('głowa', 'head', 'голова', 'noun', 'feminine', 'B1', 520, 'gwɔva', 'Boli mnie głowa.', 'My head hurts.', 'У меня болит голова.'),
('gardło', 'throat', 'горло', 'noun', 'neuter', 'B1', 521, 'gardwɔ', 'Boli mnie gardło.', 'My throat hurts.', 'У меня болит горло.'),
('brzuch', 'stomach/belly', 'живот', 'noun', 'masculine', 'B1', 522, 'bʐux', 'Boli mnie brzuch.', 'My stomach hurts.', 'У меня болит живот.'),
('plecy', 'back', 'спина', 'noun', 'plural', 'B1', 523, 'plɛt͡sɨ', 'Bolą mnie plecy.', 'My back hurts.', 'У меня болит спина.'),
('noga', 'leg', 'нога', 'noun', 'feminine', 'B1', 524, 'nɔga', 'Złamałem nogę.', 'I broke my leg.', 'Я сломал ногу.'),
('ręka', 'hand/arm', 'рука', 'noun', 'feminine', 'B1', 525, 'rɛŋka', 'Boli mnie ręka.', 'My arm hurts.', 'У меня болит рука.'),
('gorączka', 'fever', 'жар', 'noun', 'feminine', 'B1', 526, 'gɔrɔ̃t͡ʂka', 'Mam gorączkę.', 'I have a fever.', 'У меня жар.'),
('kaszel', 'cough', 'кашель', 'noun', 'masculine', 'B1', 527, 'kaʃɛl', 'Mam kaszel.', 'I have a cough.', 'У меня кашель.'),
('katar', 'runny nose, cold', 'насморк', 'noun', 'masculine', 'B1', 528, 'katar', 'Mam katar.', 'I have a runny nose.', 'У меня насморк.'),
('mdłości', 'nausea', 'тошнота', 'noun', 'plural', 'B1', 529, 'mdwɔɕt͡ɕi', 'Mam mdłości.', 'I feel nauseous.', 'Меня тошнит.'),
('zawroty głowy', 'dizziness', 'головокружение', 'noun phrase', NULL, 'B1', 530, 'zavrɔtɨ gwɔvɨ', 'Mam zawroty głowy.', 'I feel dizzy.', 'У меня кружится голова.'),
('grypa', 'flu', 'грипп', 'noun', 'feminine', 'B1', 531, 'grɨpa', 'Mam grypę.', 'I have the flu.', 'У меня грипп.'),
('przeziębienie', 'cold', 'простуда', 'noun', 'neuter', 'B1', 532, 'pʂɛʑɛmbʲɛɲɛ', 'To tylko przeziębienie.', 'It''s just a cold.', 'Это просто простуда.'),
('recepta', 'prescription', 'рецепт', 'noun', 'feminine', 'B1', 533, 'rɛt͡sɛpta', 'Potrzebuję recepty.', 'I need a prescription.', 'Мне нужен рецепт.'),
('lekarstwo', 'medicine', 'лекарство', 'noun', 'neuter', 'B1', 534, 'lɛkarst fɔ', 'Biorę lekarstwo.', 'I''m taking medicine.', 'Я принимаю лекарство.'),
('tabletka', 'pill, tablet', 'таблетка', 'noun', 'feminine', 'B1', 535, 'tablɛtka', 'Weź tabletkę.', 'Take a pill.', 'Прими таблетку.'),
('szpital', 'hospital', 'больница', 'noun', 'masculine', 'B1', 536, 'ʃpital', 'Jestem w szpitalu.', 'I''m in the hospital.', 'Я в больнице.'),
('apteka', 'pharmacy', 'аптека', 'noun', 'feminine', 'B1', 537, 'aptɛka', 'Idę do apteki.', 'I''m going to the pharmacy.', 'Я иду в аптеку.'),
('wizyta', 'appointment, visit', 'визит, приём', 'noun', 'feminine', 'B1', 538, 'vizɨta', 'Umówiłem wizytę u lekarza.', 'I made a doctor''s appointment.', 'Я записался на приём к врачу.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('bilet', 'ticket', 'билет', 'noun', 'masculine', 'B1', 539, 'bilɛt', 'Kupiłem bilet.', 'I bought a ticket.', 'Я купил билет.'),
('pociąg', 'train', 'поезд', 'noun', 'masculine', 'B1', 540, 'pɔt͡ɕɔŋk', 'Jadę pociągiem.', 'I''m going by train.', 'Я еду поездом.'),
('autobus', 'bus', 'автобус', 'noun', 'masculine', 'B1', 541, 'autɔbus', 'Czekam na autobus.', 'I''m waiting for the bus.', 'Я жду автобус.'),
('tramwaj', 'tram', 'трамвай', 'noun', 'masculine', 'B1', 542, 'tramvaj', 'Jadę tramwajem.', 'I''m going by tram.', 'Я еду трамваем.'),
('samolot', 'airplane', 'самолёт', 'noun', 'masculine', 'B1', 543, 'samɔlɔt', 'Lecę samolotem.', 'I''m flying by plane.', 'Я лечу самолётом.'),
('dworzec', 'station', 'вокзал', 'noun', 'masculine', 'B1', 544, 'dvɔʐɛt͡s', 'Jestem na dworcu.', 'I''m at the station.', 'Я на вокзале.'),
('lotnisko', 'airport', 'аэропорт', 'noun', 'neuter', 'B1', 545, 'lɔtɲiskɔ', 'Jadę na lotnisko.', 'I''m going to the airport.', 'Я еду в аэропорт.'),
('przystanek', 'stop', 'остановка', 'noun', 'masculine', 'B1', 546, 'pʂɨstanɛk', 'Wysiadam na następnym przystanku.', 'I''m getting off at the next stop.', 'Я выхожу на следующей остановке.'),
('peron', 'platform', 'перрон', 'noun', 'masculine', 'B1', 547, 'pɛrɔn', 'Pociąg odjeżdża z peronu 3.', 'The train departs from platform 3.', 'Поезд отправляется с перрона 3.'),
('rozkład jazdy', 'timetable', 'расписание', 'noun phrase', NULL, 'B1', 548, 'rɔskwat jazdɨ', 'Sprawdzam rozkład jazdy.', 'I''m checking the timetable.', 'Я проверяю расписание.'),
('przesiadka', 'transfer, connection', 'пересадка', 'noun', 'feminine', 'B1', 549, 'pʂɛɕatka', 'Czy jest przesiadka?', 'Is there a transfer?', 'Есть пересадка?'),
('opóźnienie', 'delay', 'задержка', 'noun', 'neuter', 'B1', 550, 'ɔpuʑɲɛɲɛ', 'Pociąg ma opóźnienie.', 'The train is delayed.', 'У поезда задержка.'),
('podróż', 'journey, trip', 'путешествие', 'noun', 'feminine', 'B1', 551, 'pɔdruʃ', 'Podróż trwa 3 godziny.', 'The journey takes 3 hours.', 'Путешествие длится 3 часа.'),
('bagaż', 'luggage', 'багаж', 'noun', 'masculine', 'B1', 552, 'bagaʃ', 'Gdzie jest mój bagaż?', 'Where is my luggage?', 'Где мой багаж?'),
('walizka', 'suitcase', 'чемодан', 'noun', 'feminine', 'B1', 553, 'valizka', 'Pakuję walizkę.', 'I''m packing a suitcase.', 'Я пакую чемодан.'),
('kierunek', 'direction', 'направление', 'noun', 'masculine', 'B1', 554, 'kʲɛrunɛk', 'W jakim kierunku?', 'In which direction?', 'В каком направлении?'),
('droga', 'road, way', 'дорога', 'noun', 'feminine', 'B1', 555, 'drɔga', 'Zgubiłem się w drodze.', 'I got lost on the way.', 'Я заблудился по дороге.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('święto', 'holiday, feast', 'праздник', 'noun', 'neuter', 'B1', 556, 'ɕfjɛntɔ', 'Dziś jest święto.', 'Today is a holiday.', 'Сегодня праздник.'),
('Boże Narodzenie', 'Christmas', 'Рождество', 'noun phrase', NULL, 'B1', 557, 'bɔʐɛ narɔd͡zɛɲɛ', 'Świętuję Boże Narodzenie.', 'I celebrate Christmas.', 'Я праздную Рождество.'),
('Wigilia', 'Christmas Eve', 'Сочельник', 'noun', 'feminine', 'B1', 558, 'vigʲilja', 'Wigilia jest 24 grudnia.', 'Christmas Eve is December 24.', 'Сочельник 24 декабря.'),
('Wielkanoc', 'Easter', 'Пасха', 'noun', 'feminine', 'B1', 559, 'vʲɛlkanɔt͡s', 'Wesołej Wielkanocy!', 'Happy Easter!', 'Счастливой Пасхи!'),
('tradycja', 'tradition', 'традиция', 'noun', 'feminine', 'B1', 560, 'tradɨt͡sja', 'To polska tradycja.', 'This is a Polish tradition.', 'Это польская традиция.'),
('zwyczaj', 'custom', 'обычай', 'noun', 'masculine', 'B1', 561, 'zvɨt͡ʂaj', 'To stary zwyczaj.', 'This is an old custom.', 'Это старый обычай.'),
('imieniny', 'name day', 'именины', 'noun', 'plural', 'B1', 562, 'imʲɛɲinɨ', 'Mam imieniny 15 maja.', 'My name day is May 15.', 'Мои именины 15 мая.'),
('urodziny', 'birthday', 'день рождения', 'noun', 'plural', 'B1', 563, 'urɔd͡zinɨ', 'Mam urodziny jutro.', 'My birthday is tomorrow.', 'Мой день рождения завтра.'),
('obchodzić', 'to celebrate', 'отмечать', 'verb', NULL, 'B1', 564, 'ɔpxɔd͡zit͡ɕ', 'Obchodzimy rocznicę.', 'We celebrate an anniversary.', 'Мы отмечаем годовщину.'),
('świętować', 'to celebrate, party', 'праздновать', 'verb', NULL, 'B1', 565, 'ɕfjɛntɔvat͡ɕ', 'Świętujemy Nowy Rok.', 'We celebrate New Year.', 'Мы празднуем Новый год.'),
('prezent', 'gift, present', 'подарок', 'noun', 'masculine', 'B1', 566, 'prɛzɛnt', 'Kupiłem prezent.', 'I bought a gift.', 'Я купил подарок.'),
('tort', 'cake', 'торт', 'noun', 'masculine', 'B1', 567, 'tɔrt', 'Zjedzmy tort.', 'Let''s eat cake.', 'Давайте съедим торт.'),
('choinka', 'Christmas tree', 'ёлка', 'noun', 'feminine', 'B1', 568, 'xɔjŋka', 'Ubieramy choinkę.', 'We''re decorating the Christmas tree.', 'Мы украшаем ёлку.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('firma', 'company', 'фирма', 'noun', 'feminine', 'B1', 569, 'firma', 'Pracuję w dużej firmie.', 'I work in a big company.', 'Я работаю в большой фирме.'),
('biuro', 'office', 'офис', 'noun', 'neuter', 'B1', 570, 'bʲurɔ', 'Idę do biura.', 'I''m going to the office.', 'Я иду в офис.'),
('szef', 'boss', 'начальник', 'noun', 'masculine', 'B1', 571, 'ʃɛf', 'Mój szef jest miły.', 'My boss is nice.', 'Мой начальник милый.'),
('kolega', 'colleague (m)', 'коллега', 'noun', 'masculine', 'B1', 572, 'kɔlɛga', 'To mój kolega z pracy.', 'This is my colleague from work.', 'Это мой коллега по работе.'),
('koleżanka', 'colleague (f)', 'коллега (ж)', 'noun', 'feminine', 'B1', 573, 'kɔlɛʐaŋka', 'Koleżanka mi pomogła.', 'My colleague helped me.', 'Коллега мне помогла.'),
('spotkanie', 'meeting', 'встреча', 'noun', 'neuter', 'B1', 574, 'spɔtkaɲɛ', 'Mam spotkanie o 10:00.', 'I have a meeting at 10.', 'У меня встреча в 10:00.'),
('rozmowa kwalifikacyjna', 'job interview', 'собеседование', 'noun phrase', NULL, 'B1', 575, 'rɔzmɔva kvalifikat͡sɨjna', 'Mam rozmowę kwalifikacyjną.', 'I have a job interview.', 'У меня собеседование.'),
('CV', 'CV, resume', 'резюме', 'noun', 'neuter', 'B1', 576, 't͡sɛvɛ', 'Wysłałem CV.', 'I sent my CV.', 'Я отправил резюме.'),
('umowa', 'contract', 'контракт', 'noun', 'feminine', 'B1', 577, 'umɔva', 'Podpisałem umowę.', 'I signed a contract.', 'Я подписал контракт.'),
('wynagrodzenie', 'salary', 'зарплата', 'noun', 'neuter', 'B1', 578, 'vɨnаgrɔd͡zɛɲɛ', 'Jakie jest wynagrodzenie?', 'What is the salary?', 'Какая зарплата?'),
('pensja', 'salary, wage', 'зарплата', 'noun', 'feminine', 'B1', 579, 'pɛnsja', 'Dostałem pensję.', 'I got my salary.', 'Я получил зарплату.'),
('urlop', 'vacation, leave', 'отпуск', 'noun', 'masculine', 'B1', 580, 'urlɔp', 'Idę na urlop.', 'I''m going on vacation.', 'Я иду в отпуск.'),
('raport', 'report', 'отчёт', 'noun', 'masculine', 'B1', 581, 'rapɔrt', 'Piszę raport.', 'I''m writing a report.', 'Я пишу отчёт.'),
('projekt', 'project', 'проект', 'noun', 'masculine', 'B1', 582, 'prɔjɛkt', 'Pracuję nad projektem.', 'I''m working on a project.', 'Я работаю над проектом.'),
('termin', 'deadline, date', 'срок', 'noun', 'masculine', 'B1', 583, 'tɛrmin', 'Jaki jest termin?', 'What is the deadline?', 'Какой срок?');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('gdyby', 'if (conditional)', 'если бы', 'conjunction', NULL, 'B2', 900, 'gdɨbɨ', 'Gdybym miał czas, pojechałbym.', 'If I had time, I would go.', 'Если бы у меня было время, я бы поехал.'),
('możliwość', 'possibility, opportunity', 'возможность', 'noun', 'feminine', 'B2', 901, 'mɔʐlivɔɕt͡ɕ', 'To dobra możliwość.', 'This is a good opportunity.', 'Это хорошая возможность.'),
('prawdopodobnie', 'probably', 'вероятно', 'adverb', NULL, 'B2', 902, 'pravdɔpɔdɔbɲɛ', 'Prawdopodobnie przyjdę.', 'I''ll probably come.', 'Я, вероятно, приду.'),
('być może', 'perhaps, maybe', 'возможно', 'adverb', NULL, 'B2', 903, 'bɨt͡ɕ mɔʐɛ', 'Być może masz rację.', 'Perhaps you''re right.', 'Возможно, ты прав.'),
('z pewnością', 'certainly', 'безусловно', 'adverb', NULL, 'B2', 904, 'z pɛvnɔɕt͡ɕɔŋ', 'Z pewnością przyjdę.', 'I''ll certainly come.', 'Я безусловно приду.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('zostać', 'to become, to be (passive)', 'стать', 'verb', NULL, 'B2', 905, 'zɔstat͡ɕ', 'Dom został zbudowany.', 'The house was built.', 'Дом был построен.'),
('zbudowany', 'built (passive participle)', 'построенный', 'participle', 'masculine', 'B2', 906, 'zbudɔvanɨ', 'Dom jest zbudowany.', 'The house is built.', 'Дом построен.'),
('napisany', 'written (passive participle)', 'написанный', 'participle', 'masculine', 'B2', 907, 'napisanɨ', 'List jest napisany.', 'The letter is written.', 'Письмо написано.'),
('stworzony', 'created (passive participle)', 'созданный', 'participle', 'masculine', 'B2', 908, 'stfɔʐɔnɨ', 'Film został stworzony.', 'The film was created.', 'Фильм был создан.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('twierdzić', 'to claim, assert', 'утверждать', 'verb', NULL, 'B2', 909, 'tfjɛrd͡zit͡ɕ', 'Twierdzi, że ma rację.', 'He claims he''s right.', 'Он утверждает, что прав.'),
('zaprzeczać', 'to deny', 'отрицать', 'verb', NULL, 'B2', 910, 'zapʂɛt͡ʂat͡ɕ', 'Zaprzecza oskarżeniom.', 'He denies the accusations.', 'Он отрицает обвинения.'),
('potwierdzać', 'to confirm', 'подтверждать', 'verb', NULL, 'B2', 911, 'pɔtfjɛrd͡zat͡ɕ', 'Potwierdzam rezerwację.', 'I confirm the reservation.', 'Я подтверждаю бронирование.'),
('wyjaśniać', 'to explain', 'объяснять', 'verb', NULL, 'B2', 912, 'vɨjaɕɲat͡ɕ', 'Wyjaśniam sytuację.', 'I''m explaining the situation.', 'Я объясняю ситуацию.');
INSERT INTO vocabulary (polish_word, translation_en, translation_ru, part_of_speech, gender, level, frequency_rank, pronunciation_ipa, example_sentence_pl, example_sentence_en, example_sentence_ru) VALUES
('społeczeństwo', 'society', 'общество', 'noun', 'neuter', 'B2', 913, 'spɔwɛt͡ʂɛɲstfɔ', 'Współczesne społeczeństwo.', 'Modern society.', 'Современное общество.'),
('polityka', 'politics', 'политика', 'noun', 'feminine', 'B2', 914, 'pɔlitɨka', 'Interesuję się polityką.', 'I''m interested in politics.', 'Я интересуюсь политикой.'),
('gospodarka', 'economy', 'экономика', 'noun', 'feminine', 'B2', 915, 'gɔspɔdarka', 'Polska gospodarka.', 'Polish economy.', 'Польская экономика.'),
('środowisko', 'environment', 'окружающая среда', 'noun', 'neuter', 'B2', 916, 'ɕrɔdɔviskɔ', 'Ochrona środowiska.', 'Environmental protection.', 'Защита окружающей среды.'),
('zanieczyszczenie', 'pollution', 'загрязнение', 'noun', 'neuter', 'B2', 917, 'zaɲɛt͡ʂɨʃt͡ʂɛɲɛ', 'Zanieczyszczenie powietrza.', 'Air pollution.', 'Загрязнение воздуха.'),
('zmiana klimatu', 'climate change', 'изменение климата', 'noun phrase', NULL, 'B2', 918, 'zmʲana klimatu', 'Walka ze zmianą klimatu.', 'Fighting climate change.', 'Борьба с изменением климата.'),
('równość', 'equality', 'равенство', 'noun', 'feminine', 'B2', 919, 'ruvnɔɕt͡ɕ', 'Równość płci.', 'Gender equality.', 'Гендерное равенство.'),
('sprawiedliwość', 'justice', 'справедливость', 'noun', 'feminine', 'B2', 920, 'spravʲɛdlivɔɕt͡ɕ', 'Walka o sprawiedliwość.', 'Fighting for justice.', 'Борьба за справедливость.');
